+      depth: parts.length - 1,
+    }
+    allNodes.set(dirPath, node)
+  }
+
+  // Build file nodes
+  for (const f of files) {
+    const node: TreeNode = {
+      id: `file:${f.path}`,
+      name: f.name,
+      path: f.path,
+      kind: 'file',
+      language: f.language !== 'unknown' ? f.language : undefined,
+      fileId: f.id,
+      size: f.size,
+      children: [],
+      depth: f.path.split('/').length - 1,
+    }
+    allNodes.set(f.path, node)
+  }
+
+  // Build parent-child relationships
+  for (const [path, node] of allNodes) {
+    const parts = path.split('/')
+    if (parts.length === 1) {
+      root.set(path, node)
+    } else {
+      const parentPath = parts.slice(0, -1).join('/')
+      const parent = allNodes.get(parentPath)
+      if (parent) {
+        parent.children.push(node)
+      } else {
+        root.set(path, node)
+      }
+    }
+  }
+
+  // Sort: directories before files, then alphabetically
+  function sortNodes(nodes: TreeNode[]): TreeNode[] {
+    nodes.sort((a, b) => {
+      if (a.kind !== b.kind) return a.kind === 'directory' ? -1 : 1
+      return a.name.localeCompare(b.name)
+    })
+    for (const n of nodes) sortNodes(n.children)
+    return nodes
+  }
+
+  return sortNodes(Array.from(root.values()))
+}
+
+function filterTree(nodes: TreeNode[], query: string): TreeNode[] {
+  if (!query) return nodes
+  const q = query.toLowerCase()
+
+  function matchNode(node: TreeNode): TreeNode | null {
+    if (node.kind === 'file') {
+      return node.path.toLowerCase().includes(q) ? node : null
+    }
+    const matchedChildren = node.children.flatMap(c => {
+      const m = matchNode(c)
+      return m ? [m] : []
+    })
+    if (matchedChildren.length > 0 || node.path.toLowerCase().includes(q)) {
+      return { ...node, children: matchedChildren }
+    }
+    return null
+  }
+
+  return nodes.flatMap(n => {
+    const m = matchNode(n)
+    return m ? [m] : []
+  })
+}
+
+// ── Language to short label ────────────────────────────────────────────────
+
+const LANG_SHORT: Record<string, string> = {
+  python: 'py',
+  typescript: 'ts',
+  javascript: 'js',
+  go: 'go',
+  rust: 'rs',
+  java: 'java',
+  css: 'css',
+  html: 'html',
+  json: 'json',
+  markdown: 'md',
+  yaml: 'yaml',
+  toml: 'toml',
+  shell: 'sh',
+  sql: 'sql',
+}
+
+// ── Icons ──────────────────────────────────────────────────────────────────
+
+function FolderIcon({ open }: { open: boolean }) {
+  return (
+    <svg
+      className="tree-node__icon"
+      viewBox="0 0 14 14"
+      fill="none"
+      aria-hidden="true"
+    >
+      {open ? (
+        <path d="M1 3.5h12v8H1z M1 3.5l2-2h3l1 1.5H1" fill="#dce5af" stroke="#a1a77d" strokeWidth="1" />
+      ) : (
+        <path d="M1 4.5h12v7H1z M1 4.5l2-2h3l1 2H1" fill="#dce5af" stroke="#a1a77d" strokeWidth="1" />
+      )}
+    </svg>
+  )
+}
+
+function FileIcon({ language }: { language?: string }) {
+  const color = language === 'python' ? '#366bad'
+    : language === 'typescript' || language === 'javascript' ? '#d4a017'
+    : '#8a9a86'
+  return (
+    <svg
+      className="tree-node__icon"
+      viewBox="0 0 14 14"
+      fill="none"
+      aria-hidden="true"
+    >
+      <rect x="2" y="1" width="8" height="12" rx="1" fill="white" stroke={color} strokeWidth="1" />
+      <path d="M8 1v3h2" stroke={color} strokeWidth="1" />
+      <line x1="4" y1="7" x2="10" y2="7" stroke={color} strokeWidth="0.8" />
+      <line x1="4" y1="9" x2="8" y2="9" stroke={color} strokeWidth="0.8" />
+    </svg>
+  )
+}
+
+function ChevronIcon({ open }: { open: boolean }) {
+  return (
+    <svg
+      className={`tree-node__chevron ${open ? 'tree-node__chevron--open' : ''}`}
+      viewBox="0 0 14 14"
+      fill="none"
+      aria-hidden="true"
+    >
+      <path d="M5 3l4 4-4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
+    </svg>
+  )
+}
+
+// ── Single tree node ───────────────────────────────────────────────────────
+
+interface TreeNodeProps {
+  node: TreeNode
+  selectedPath: string | null
+  expandedPaths: Set<string>
+  onSelect: (node: TreeNode) => void
+  onToggle: (path: string) => void
+  depth: number
+}
+
+function TreeNodeRow({
+  node,
+  selectedPath,
+  expandedPaths,
+  onSelect,
+  onToggle,
+  depth,
+}: TreeNodeProps) {
+  const isExpanded = expandedPaths.has(node.path)
+  const isSelected = selectedPath === node.path
+  const isDir = node.kind === 'directory'
+  const langShort = node.language ? (LANG_SHORT[node.language] ?? node.language.slice(0, 4)) : undefined
+
+  function handleClick() {
+    if (isDir) {
+      onToggle(node.path)
+    } else {
+      onSelect(node)
+    }
+  }
+
+  function handleKeyDown(e: React.KeyboardEvent) {
+    if (e.key === 'Enter' || e.key === ' ') {
+      e.preventDefault()
+      handleClick()
+    }
+    if (e.key === 'ArrowRight' && isDir && !isExpanded) {
+      onToggle(node.path)
+    }
+    if (e.key === 'ArrowLeft' && isDir && isExpanded) {
+      onToggle(node.path)
+    }
+  }
+
+  return (
+    <>
+      <button
+        type="button"
+        className={`tree-node ${isSelected ? 'tree-node--selected' : ''}`}
+        style={{ paddingLeft: `${8 + depth * 14}px` }}
+        onClick={handleClick}
+        onKeyDown={handleKeyDown}
+        aria-expanded={isDir ? isExpanded : undefined}
+        aria-selected={isSelected}
+        title={node.path}
+        tabIndex={0}
+      >
+        {isDir ? (
+          <ChevronIcon open={isExpanded} />
+        ) : (
+          <span className="tree-node__chevron tree-node__chevron--leaf" aria-hidden="true" />
+        )}
+
+        {isDir ? <FolderIcon open={isExpanded} /> : <FileIcon language={node.language} />}
+
+        <span className="tree-node__label">{node.name}</span>
+
+        {langShort && !isDir && (
+          <span className="tree-node__lang" aria-label={`Language: ${node.language}`}>
+            {langShort}
+          </span>
+        )}
+      </button>
+
+      {isDir && isExpanded && node.children.map(child => (
+        <TreeNodeRow
+          key={child.id}
+          node={child}
+          selectedPath={selectedPath}
+          expandedPaths={expandedPaths}
+          onSelect={onSelect}
+          onToggle={onToggle}
+          depth={depth + 1}
+        />
+      ))}
+    </>
+  )
+}
+
+// ── Repository tree component ──────────────────────────────────────────────
+
+interface RepositoryTreeProps {
+  files: FileRecord[]
+  selectedPath: string | null
+  onSelect: (file: FileRecord) => void
+}
+
+export function RepositoryTree({ files, selectedPath, onSelect }: RepositoryTreeProps) {
+  const [search, setSearch] = useState('')
+  const [expandedPaths, setExpandedPaths] = useState<Set<string>>(new Set())
+  const searchRef = useRef<HTMLInputElement>(null)
+
+  const tree = useMemo(() => buildTree(files), [files])
+  const filteredTree = useMemo(() => filterTree(tree, search), [tree, search])
+
+  // Auto-expand all directories when searching
+  useEffect(() => {
+    if (search) {
+      const dirs = new Set<string>()
+      function collect(nodes: TreeNode[]) {
+        for (const n of nodes) {
+          if (n.kind === 'directory') {
+            dirs.add(n.path)
+            collect(n.children)
+          }
+        }
+      }
+      collect(filteredTree)
+      setExpandedPaths(dirs)
+    }
+  }, [search, filteredTree])
+
+  // Auto-expand to selected path
+  useEffect(() => {
+    if (selectedPath) {
+      const parts = selectedPath.split('/')
+      const toExpand = new Set(expandedPaths)
+      for (let i = 1; i < parts.length; i++) {
+        toExpand.add(parts.slice(0, i).join('/'))
+      }
+      setExpandedPaths(toExpand)
+    }
+  // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [selectedPath])
+
+  const handleToggle = useCallback((path: string) => {
+    setExpandedPaths(prev => {
+      const next = new Set(prev)
+      if (next.has(path)) next.delete(path)
+      else next.add(path)
+      return next
+    })
+  }, [])
+
+  const handleSelect = useCallback((node: TreeNode) => {
+    if (node.kind === 'file') {
+      const file = files.find(f => f.path === node.path)
+      if (file) onSelect(file)
+    }
+  }, [files, onSelect])
+
+  const fileCount = files.filter(f => true).length
+
+  return (
+    <>
+      <div className="tree-panel__header">
+        <h2 className="tree-panel__title" id="tree-heading">Files</h2>
+        <span className="tree-panel__count" aria-label={`${fileCount} files`}>
+          {fileCount}
+        </span>
+      </div>
+
+      <div className="tree-panel__search">
+        <input
+          ref={searchRef}
+          type="search"
+          className="tree-search-input"
+          placeholder="Search files…"
+          value={search}
+          onChange={e => setSearch(e.target.value)}
+          aria-label="Search files"
+          aria-controls="tree-list"
+        />
+      </div>
+
+      <div
+        className="tree-panel__scroll"
+        role="tree"
+        id="tree-list"
+        aria-labelledby="tree-heading"
+        aria-label="Repository file tree"
+      >
+        {filteredTree.length === 0 ? (
+          <p className="tree-message">
+            {search ? `No files matching "${search}"` : 'No files in this snapshot.'}
+          </p>
+        ) : (
+          filteredTree.map(node => (
+            <TreeNodeRow
+              key={node.id}
+              node={node}
+              selectedPath={selectedPath}
+              expandedPaths={expandedPaths}
+              onSelect={handleSelect}
+              onToggle={handleToggle}
+              depth={0}
+            />
+          ))
+        )}
+      </div>
+    </>
+  )
+}
